import sys
sys.path.insert(0,'/workspace/tools')
from pngread import pixels
def ink(path,thresh=200):
    w,h,px,ct=pixels(path)
    cols=set(); rows=set()
    for y in range(h):
        for x in range(w):
            p=px[y][x]
            v=(p[0]+p[1]+p[2])//3
            if v<thresh:
                cols.add(x); rows.add(y)
    if not cols: return None
    return (min(cols),max(cols),min(rows),max(rows), max(cols)-min(cols)+1, max(rows)-min(rows)+1)
if __name__=='__main__':
    for f in sys.argv[1:]:
        print(f, ink(f))
